import{_ as e,o as t,c as i,l as a,t as o,N as n}from"./chunks/framework.Gjrf2Eoj.js";const F=JSON.parse('{"title":"docker-volume-create | x-cmd man (docker man1) | Create a volume","titleTemplate":false,"description":"x-cmd man (docker man1 Manual Page) | docker-volume-create - Create a volume","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"docker-volume-create | x-cmd man (docker man1) | Create a volume"}],["meta",{"name":"og:description","content":"x-cmd man (docker man1 Manual Page) | docker-volume-create - Create a volume"}]]},"headers":[],"params":{"isMan":true,"man":"docker-volume-create","category":"docker man1","desc":"Create a volume"},"relativePath":"docker/man1/docker-volume-create.md","filePath":"docker/man1/docker-volume-create.md"}'),r={name:"docker/man1/docker-volume-create.md"},l={class:"visually-hidden"},p=n(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>docker-volume-create - Create a volume</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>docker volume create [OPTIONS] [VOLUME]</strong></p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Creates a new volume that containers can consume and store data in. If a name is not specified, Docker generates a random name. You create a volume and then configure the container to use it, for example:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> volume</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hello</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello:/world</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> busybox</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ls</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /world</span></span></code></pre></div><p>The mount is created inside the container&#39;s <strong>/src</strong> directory. Docker does not support relative paths for mount points inside the container.</p><p>Multiple containers can use the same volume in the same time period. This is useful if two containers need access to shared data. For example, if one container writes and the other reads the data.</p><h2 id="driver-specific-options" tabindex="-1">Driver specific options <a class="header-anchor" href="#driver-specific-options" aria-label="Permalink to &quot;Driver specific options&quot;">​</a></h2><p>Some volume drivers may take options to customize the volume creation. Use the <strong>-o</strong> or <strong>--opt</strong> flags to pass driver options:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> volume</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --driver</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --opt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tardis=blue</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --opt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> timey=wimey</span></span></code></pre></div><p>These options are passed directly to the volume driver. Options for different volume drivers may do different things (or nothing at all).</p><p>The built-in <strong>local</strong> driver on Windows does not support any options.</p><p>The built-in <strong>local</strong> driver on Linux accepts options similar to the linux <strong>mount</strong> command:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> volume</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --driver</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> local</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --opt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> type=tmpfs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --opt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> device=tmpfs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --opt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> o=size=100m,uid=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1000</span></span></code></pre></div><p>Another example:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> volume</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --driver</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> local</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --opt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> type=btrfs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --opt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> device=/dev/sda2</span></span></code></pre></div><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p><strong>--availability</strong>=&quot;active&quot; Cluster Volume availability (&quot;active&quot;, &quot;pause&quot;, &quot;drain&quot;)</p><p><strong>-d</strong>, <strong>--driver</strong>=&quot;local&quot; Specify volume driver name</p><p><strong>--group</strong>=&quot;&quot; Cluster Volume group (cluster volumes)</p><p><strong>-h</strong>, <strong>--help</strong>[=false] help for create</p><p><strong>--label</strong>= Set metadata for a volume</p><p><strong>--limit-bytes</strong>=0 Minimum size of the Cluster Volume in bytes</p><p><strong>-o</strong>, <strong>--opt</strong>=map[] Set driver specific options</p><p><strong>--required-bytes</strong>=0 Maximum size of the Cluster Volume in bytes</p><p><strong>--scope</strong>=&quot;single&quot; Cluster Volume access scope (&quot;single&quot;, &quot;multi&quot;)</p><p><strong>--secret</strong>=map[] Cluster Volume secrets</p><p><strong>--sharing</strong>=&quot;none&quot; Cluster Volume access sharing (&quot;none&quot;, &quot;readonly&quot;, &quot;onewriter&quot;, &quot;all&quot;)</p><p><strong>--topology-preferred</strong>= A topology that the Cluster Volume would be preferred in</p><p><strong>--topology-required</strong>= A topology that the Cluster Volume must be accessible from</p><p><strong>--type</strong>=&quot;block&quot; Cluster Volume access type (&quot;mount&quot;, &quot;block&quot;)</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>docker-volume(1)</strong></p>`,35);function h(s,d,k,c,u,g){return t(),i("div",null,[a("h1",l,o(s.$params.man),1),p])}const C=e(r,[["render",h]]);export{F as __pageData,C as default};
